# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">AİLEM (أُسْرَتِي) — ÇEKİRDEK VE GENİŞ AİLE BİREYLERİ</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">ÇEKİRDEK AİLE (الأُسْرَةُ الصَّغِيرَةُ)</text>\n  <text x="45" y="96" font-size="12" font-weight="bold" fill="#1e3a8a">• أَبٌ / وَالِدٌ (Ebun / Vâlidun) → Baba</text>\n  <text x="45" y="122" font-size="12" font-weight="bold" fill="#1e3a8a">• أُمٌّ / وَالِدَةٌ (Ummun / Vâlidetun) → Anne</text>\n  <text x="45" y="148" font-size="12" font-weight="bold" fill="#1e3a8a">• أَخٌ (Ahun) → Erkek kardeş</text>\n  <text x="45" y="174" font-size="12" font-weight="bold" fill="#1e3a8a">• أُخْتٌ (Uhtun) → Kız kardeş</text>\n  <text x="45" y="200" font-size="12" font-weight="bold" fill="#1e3a8a">• اِبْنٌ / بِنْتٌ (İbnun / Bintun) → Oğul / Kız evlat</text>\n  <text x="182" y="226" text-anchor="middle" font-size="11" fill="#1d4ed8">أُسْرَتِي سَعِيدَةٌ (Benim ailem mutludur.)</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#fdf2f8" stroke="#db2777" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#9d174d">GENİŞ AİLE VE AKRABALAR (الأَقَارِبُ)</text>\n  <text x="380" y="96" font-size="12" font-weight="bold" fill="#831843">• جَدٌّ / جَدَّةٌ (Ceddun / Ceddetun) → Dede / Nine</text>\n  <text x="380" y="122" font-size="12" font-weight="bold" fill="#831843">• عَمٌّ / عَمَّةٌ (Ammun / Ammetun) → Amca / Hala</text>\n  <text x="380" y="148" font-size="12" font-weight="bold" fill="#831843">• خَالٌ / خَالَةٌ (Hâlun / Hâletun) → Dayı / Teyze</text>\n  <text x="380" y="174" font-size="12" font-weight="bold" fill="#831843">• زَوْجٌ / زَوْجَةٌ (Zevcun / Zevcetun) → Eş (Koca / Karı)</text>\n  <text x="380" y="200" font-size="12" font-weight="bold" fill="#831843">• حَفِيدٌ / حَفِيدَةٌ (Hafîdun / Hafîdetun) → Torun (E / K)</text>\n  <text x="517" y="226" text-anchor="middle" font-size="11" fill="#be185d">Baba tarafı: عَمٌّ / عَمَّةٌ · Anne tarafı: خَالٌ / خَالَةٌ</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">BİTİŞİK İYELİK ZAMİRLERİ (الضَّمَائِرُ الْمُتَّصِلَةُ) İLE AİLE BİREYLERİ</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">TEKİL İYELİK ZAMİRİ EKLERİ</text>\n  <text x="45" y="96" font-size="11.5" font-weight="bold" fill="#14532d">• ـي (Benim — أَنَا): أَبِي (Babam), أُمِّي (Annem)</text>\n  <text x="45" y="124" font-size="11.5" font-weight="bold" fill="#14532d">• ـكَ (Senin [E] — أَنْتَ): أَبُوكَ / وَالِدُكَ، أُمُّكَ</text>\n  <text x="45" y="152" font-size="11.5" font-weight="bold" fill="#14532d">• ـكِ (Senin [K] — أَنْتِ): أَبُوكِ / وَالِدُكِ، أُمُّكِ</text>\n  <text x="45" y="180" font-size="11.5" font-weight="bold" fill="#14532d">• ـهُ (Onun [E] — هُوَ): أَبُوهُ / وَالِدُهُ، أُخْتُهُ</text>\n  <text x="45" y="208" font-size="11.5" font-weight="bold" fill="#14532d">• ـهَا (Onun [K] — هِيَ): أَبُوهَا / وَالِدُهَا، أَخُوهَا</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#854d0e">YUVARLAK TÂ (ة) HARFİNİN AÇILMASI</text>\n  <text x="380" y="98" font-size="11.5" font-weight="bold" fill="#713f12">Sonu ة ile biten kelimelere zamir bitiştiğinde</text>\n  <text x="380" y="116" font-size="11.5" font-weight="bold" fill="#713f12">yuvarlak tâ (ة) açık tâ (ـتـ) harfine dönüşür:</text>\n  <text x="380" y="144" font-size="11.5" fill="#713f12">• أُسْرَةٌ + ي → أُسْرَتِي (Benim ailem)</text>\n  <text x="380" y="168" font-size="11.5" fill="#713f12">• جَدَّةٌ + ي → جَدَّتِي (Benim ninem)</text>\n  <text x="380" y="192" font-size="11.5" fill="#713f12">• عَمَّةٌ + كَ → عَمَّتُكَ (Senin halan)</text>\n  <text x="380" y="216" font-size="11.5" fill="#713f12">• خَالَةٌ + هُ → خَالَتُهُ (Onun teyzesi)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">AİLE TANITIM DİYALOGLARI VE SOSYAL İFADELER</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">ÖRNEK AİLE TANITIM CÜMLELERİ</text>\n  <text x="45" y="96" font-size="11.5" font-weight="bold" fill="#581c87">• هٰذِهِ صُورَةُ أُسْرَتِي (Bu ailemin fotoğrafıdır.)</text>\n  <text x="45" y="124" font-size="11.5" font-weight="bold" fill="#581c87">• هٰذَا جَدِّي، اِسْمُهُ عُمَرُ (Bu dedemdir, adı Ömer\'dir.)</text>\n  <text x="45" y="152" font-size="11.5" font-weight="bold" fill="#581c87">• هٰذِهِ أُمِّي، هِيَ مُدَرِّسَةٌ (Bu annemdir, o öğretmendir.)</text>\n  <text x="45" y="180" font-size="11.5" font-weight="bold" fill="#581c87">• هٰذَا أَخِي الصَّغِيرُ (Bu küçük erkek kardeşimdir.)</text>\n  <text x="45" y="208" font-size="11.5" font-weight="bold" fill="#581c87">• أَنَا أُحِبُّ أُسْرَتِي كَثِيرًا (Ailemi çok seviyorum.)</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#9a3412">SOSYAL İLETİŞİM VE NEZAKET KALIPLARI</text>\n  <text x="380" y="96" font-size="11.5" font-weight="bold" fill="#7c2d12">• تَشَرَّفْتُ بِمَعْرِفَتِكَ (Tanıştığımıza memnun oldum.)</text>\n  <text x="380" y="124" font-size="11.5" font-weight="bold" fill="#7c2d12">• فُرْصَةٌ سَعِيدَةٌ (Güzel bir fırsat / Memnun oldum.)</text>\n  <text x="380" y="152" font-size="11.5" font-weight="bold" fill="#7c2d12">• وَأَنَا أَيْضًا (Ben de memnun oldum.)</text>\n  <text x="380" y="180" font-size="11.5" font-weight="bold" fill="#7c2d12">• شُكْرًا جَزِيلًا — عَفْوًا (Çok teşekkürler — Rica ederim.)</text>\n  <text x="380" y="208" font-size="11" font-weight="bold" fill="#9a3412">«اَلْكَلِمَةُ الطَّيِّبَةُ مِفْتَاحُ التَّعَارُفِ» (Güzel söz tanışmanın anahtarıdır.)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
